PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX geof: <http://www.opengis.net/def/function/geosparql/>

SELECT DISTINCT ?neighborCatchment
WHERE {
  GRAPH <hydroturtle/lamah_ce> {
    {
      SELECT ?targetCatchment ?targetWKT (SUM(?precipitationNumeric) AS ?totalPrecipitation)
      WHERE {
        ?obs a sosa:Observation ;
             sosa:observedProperty envthes:30106 ;
             sosa:resultTime ?time ;
             sosa:hasResult ?precipitationValue ;
             sosa:hasFeatureOfInterest ?targetCatchment .
        ?precipitationValue qudt:numericValue ?precipitationNumeric .
        ?targetCatchment geo:hasGeometry ?targetPolygon .
        ?targetPolygon geo:asWKT ?targetWKT ;
                       hyobs:crs <http://www.opengis.net/def/crs/OGC/1.3/CRS84> .
        FILTER(?time >= "2012-01-01T00:00:00"^^xsd:dateTime && ?time < "2016-01-01T00:00:00"^^xsd:dateTime)
      }
      GROUP BY ?targetCatchment ?targetWKT
      ORDER BY DESC(?totalPrecipitation)
      LIMIT 1
    }
    ?neighborCatchment a envthes:30212 ;
                       geo:hasGeometry ?neighborPolygon .
    ?neighborPolygon geo:asWKT ?neighborWKT ;
                     hyobs:crs <http://www.opengis.net/def/crs/OGC/1.3/CRS84> .
    FILTER(?neighborCatchment != ?targetCatchment)
    FILTER(geof:sfTouches(?targetWKT, ?neighborWKT))
  }
}

