PREFIX uom: <http://www.opengis.net/def/uom/OGC/1.0/>
PREFIX sf: <http://www.opengis.net/ont/sf#>

SELECT (geof:distance(?highWKT, ?lowWKT, uom:metre) AS ?distance)
WHERE {
  GRAPH <hydroturtle/lamah_ce> {
    ?highStation a sosa:Sensor ;
      geo:hasGeometry ?highPoint .
    ?highPoint a sf:Point ;
      wgs84_pos:alt ?highElevation ;
      geo:asWKT ?highWKT .

    ?lowStation a sosa:Sensor ;
      geo:hasGeometry ?lowPoint .
    ?lowPoint a sf:Point ;
      wgs84_pos:alt ?lowElevation ;
      geo:asWKT ?lowWKT .

    FILTER NOT EXISTS {
      ?otherHighStation a sosa:Sensor ;
        geo:hasGeometry ?otherHighPoint .
      ?otherHighPoint a sf:Point ;
        wgs84_pos:alt ?otherHighElevation .
      FILTER(xsd:double(?otherHighElevation) > xsd:double(?highElevation))
    }

    FILTER NOT EXISTS {
      ?otherLowStation a sosa:Sensor ;
        geo:hasGeometry ?otherLowPoint .
      ?otherLowPoint a sf:Point ;
        wgs84_pos:alt ?otherLowElevation .
      FILTER(xsd:double(?otherLowElevation) < xsd:double(?lowElevation))
    }
  }
}
LIMIT 1

actual_sparql:
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX geo:  <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX wgs84_pos: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

SELECT ?highestSensor ?highestEle ?lowestSensor ?lowestEle ?distance
WHERE {
  GRAPH <hydroturtle/lamah_ce> {

    # --- highest elevation station ---
    {
      SELECT ?highestSensor ?highestEle ?wktHigh
      WHERE {
        ?highestSensor a sosa:Sensor ;
                      geo:hasGeometry ?gHigh .
        ?gHigh wgs84_pos:alt ?highestEle ;
              geo:asWKT ?wktHigh .
      }
      ORDER BY DESC(xsd:decimal(?highestEle))
      LIMIT 1
    }

    # --- lowest elevation station ---
    {
      SELECT ?lowestSensor ?lowestEle ?wktLow
      WHERE {
        ?lowestSensor a sosa:Sensor ;
                      geo:hasGeometry ?gLow .
        ?gLow wgs84_pos:alt ?lowestEle ;
              geo:asWKT ?wktLow .
      }
      ORDER BY xsd:decimal(?lowestEle)
      LIMIT 1
    }

    # Distance between the two station points
    BIND(bif:st_distance(?wktHigh, ?wktLow) AS ?distance)
  }
}

